const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const DRAFTS = STATE + '/drafts';
// an unguarded mkdirSync throw here killed the node before the item
// loop could answer - the moderation-draft caller saw a bare
// execution failure with no draft-level reason. Record it and let
// the loop refuse each item with the {kind:'msg', ok:false} shape
// every other refusal uses (after the secret gate below - the state
// dir's health is config state like chat_id).
let draftsDirErr = null;
try { fs.mkdirSync(DRAFTS, { recursive: true }); } catch (e) {
  draftsDirErr = String((e && e.message) || e).slice(0, 150);
}
const MEDIA_ROOT = '/home/node/materials';
const MEDIA_ROOT_REAL = (() => {
  try { return fs.realpathSync(MEDIA_ROOT); } catch (e) { return MEDIA_ROOT; }
})();
// moderation-draft is a public webhook, so media[] must never resolve
// outside the read-only materials/ mount: a bare absolute host path
// (/etc/..., a DB file) or a symlink inside materials/ pointing out
// would otherwise be read and sent back over Telegram
const underRoot = (p) => {
  try {
    const rp = fs.realpathSync(p);
    return rp === MEDIA_ROOT_REAL || rp.startsWith(MEDIA_ROOT_REAL + '/');
  } catch (e) { return false; }
};
// media paths may arrive as host paths, materials/... relatives or
// bare filenames - resolve them against the read-only mount.
const resolveMedia = (s) => {
  const p = String(s || '');
  if (!p) return null;
  const cands = [];
  const m = p.match(/(?:^|\/)materials\/(.+)$/);
  if (m) cands.push(MEDIA_ROOT + '/' + m[1]);
  if (p.startsWith('/')) cands.push(p);
  const base = p.split('/').pop();
  cands.push(MEDIA_ROOT + '/photos/' + base, MEDIA_ROOT + '/' + base);
  for (const c of cands) {
    if (fs.existsSync(c) && underRoot(c)) return c;
  }
  return null;
};
const mimeOf = (p) => (/\.png$/i.test(p) ? 'image/png'
  : /\.webp$/i.test(p) ? 'image/webp' : 'image/jpeg');

// operator chat_id is pinned config: TELEGRAM_CHAT_ID env first, the
// tg.json written by sp-tg-setup as compat fallback. It is never taken
// from incoming webhook payloads.
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
if (!chatId) {
  try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}
}
// a missing chat_id is reported per-item AFTER the secret check below:
// answering 'chat_id unknown' to an unauthenticated caller on this
// public endpoint would leak server config state

// atomic draft writes: tmp + rename - a crash mid-writeFileSync would
// leave a torn JSON, and the overwrite guard below must fail CLOSED on
// an unreadable file (it does), so never produce one here.
// SYNC: sibling copies live in Handle TG Update and Compose Message
// (this workflow), Publish Tick (sp-publish, hardened 0o600 variant),
// Generate Drafts (sp-content-gen) and Resolve Chat + Webhook
// (sp-tg-setup). n8n Code nodes cannot share a prelude - replicate
// any fix to every copy by hand.
// SYNC-BEGIN: write-json-atomic
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic

// Re-read-then-mutate draft writes - the same pattern Handle TG
// Update's updateDraft follows for every callback save: the
// rewrite-expiry seal below must not stamp the earlier-read snapshot
// back over a concurrent write, so guard(cur) vetoes the write when
// the file moved on underneath us. Read/write errors propagate - the
// caller treats a throw as 'state save failed'.
const updateDraft = (id, mutate, guard) => {
  const cur = JSON.parse(
    fs.readFileSync(DRAFTS + '/' + id + '.json', 'utf8'));
  if (guard && !guard(cur)) return null;
  mutate(cur);
  writeJsonAtomic(DRAFTS + '/' + id + '.json', cur);
  return cur;
};

// moderation-draft is reachable through the public edge proxy, so
// draft CREATION needs its own shared-secret gate - the
// TG_WEBHOOK_SECRET check on tg-moderation only covers Telegram
// deliveries, and the draft_id allowlist + overwrite guard below only
// protect EXISTING drafts. Without this, anyone who knows the URL can
// push unlimited previews with live Approve buttons into the operator
// chat (one tap = a wall.post on the real VK wall). Callers must send
// X-Shared-Token or X-TG-Draft-Secret matching DRAFT_WEBHOOK_SECRET
// (content-gen is the internal caller and sends it). Fail closed when
// the env is unset - a dead endpoint beats a public spam surface.
// Constant-time-ish compare without crypto (only fs is allowed in
// Code nodes).
// SYNC: identical padded compares live in Handle TG Update's
// secretOk (this workflow, TG_WEBHOOK_SECRET gate) and Generate
// Drafts' cgSecretOk (sp-content-gen, CONTENT_GEN_WEBHOOK_SECRET
// gate) - n8n Code nodes cannot share a prelude, so replicate any
// fix to all three copies.
const DRAFT_SECRET = ENV('DRAFT_WEBHOOK_SECRET');
// SYNC-BEGIN: padded-compare
const secretOk = (got) => {
  const a = String(got == null ? '' : got);
  if (!DRAFT_SECRET) return false;
  // no early return on a length mismatch: it leaks the expected
  // secret length through response timing on this public endpoint.
  // Pad both operands to a shared length and fold the length delta
  // into diff so a padded tail can never compare equal. The first
  // loop count is a FIXED 64 - a bound of SECRET.length would make
  // the compare cost proportional to the secret's length, the very
  // leak the floor exists to hide, and a.length stays OUT of every
  // bound so an over-long attacker header cannot stretch the compare
  // either. Positions past 64 are NOT ignored: the second loop folds
  // the tail for i < SECRET.length (a per-deployment constant), so a
  // >64 configured secret compares in full instead of degrading to a
  // prefix-only check. padEnd never truncates, and charCodeAt past
  // the end of pa yields NaN (folds as 0 ^ pb char - still a nonzero
  // diff); the length-xor above rejects whatever length mismatch is
  // left.
  const len = 64;
  const pa = a.padEnd(len, '\0');
  const pb = DRAFT_SECRET.padEnd(len, '\0');
  let diff = a.length ^ DRAFT_SECRET.length;
  for (let i = 0; i < len; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  for (let i = len; i < DRAFT_SECRET.length; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  return diff === 0;
};
// SYNC-END: padded-compare

const out = [];
for (const item of $input.all()) {
  // the webhook node passes request headers through on
  // item.json.headers (lowercased names). Reject before any draft
  // write or Telegram send - the whole body is untrusted until the
  // secret check passes. The msg-kind item below short-circuits
  // Compose Message, so a rejected call answers {ok:false} and nothing
  // reaches the operator chat.
  const hdrs = (item.json && item.json.headers) || {};
  if (!secretOk(hdrs['x-shared-token']) &&
      !secretOk(hdrs['x-tg-draft-secret'])) {
    out.push({ json: { kind: 'msg', ok: false,
      error: DRAFT_SECRET
        ? 'unauthorized - missing/invalid draft webhook secret'
        : 'unauthorized - DRAFT_WEBHOOK_SECRET not configured (fails closed)' } });
    continue;
  }
  // config checks come after the secret gate - see the chatId note above
  if (!chatId) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'chat_id unknown - set TELEGRAM_CHAT_ID or run workflow sp-tg-setup' } });
    continue;
  }
  if (draftsDirErr) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'draft store unavailable - mkdir ' + DRAFTS +
        ' failed: ' + draftsDirErr } });
    continue;
  }
  const b = item.json.body || item.json;
  // draft_id is caller-controlled on the public moderation-draft
  // webhook and lands in file paths below (draft file, TG captions,
  // queue file on Approve) - allowlist it, reject everything else:
  // a '../' would escape the drafts dir for arbitrary-path writes
  const rawId = b.draft_id;
  // a SUPPLIED draft_id must be a non-empty string: a falsy caller
  // value (0, false) slips through String(rawId) into a generated id
  // and a non-string gets coerced, so the delivered draft_id would
  // silently differ from the id the caller asked for and tracks.
  // undefined/null still means 'generate one here'.
  if (rawId !== undefined && rawId !== null &&
      (typeof rawId !== 'string' || rawId === '')) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'invalid draft_id: non-empty string expected' } });
    continue;
  }
  if (rawId !== undefined && rawId !== null &&
      !/^[A-Za-z0-9_-]+$/.test(String(rawId))) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'invalid draft_id: [A-Za-z0-9_-] only' } });
    continue;
  }
  // the id rides inside Telegram callback_data ('ap:<id>:<ver>') -
  // 64 bytes hard cap minus ~4 bytes of action prefix and ~14 bytes
  // of version token leaves ~46, capped at 40 with margin. A longer
  // id would make Telegram reject the preview's keyboard and wedge
  // the draft in 'deliver-failed' with a far less readable error
  if (rawId !== undefined && rawId !== null &&
      String(rawId).length > 40) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'invalid draft_id: 40 chars max (callback_data budget)' } });
    continue;
  }
  const id = String(rawId || 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6));
  const warnings = Array.isArray(b.warnings) ? b.warnings.map(String)
    : (b.warnings ? [String(b.warnings)] : []);
  const draft = {
    id: id,
    platform: b.platform || 'unknown',
    topic: b.topic || '',
    text: String(b.text || ''),
    // String() like the sibling fields: a non-string truthy image
    // (object/array) would otherwise land verbatim in the draft file
    // and the queue payload
    image: String(b.image || b.image_path || ''),
    media: Array.isArray(b.media) ? b.media.map(String)
      : (b.media ? [String(b.media)] : []),
    caption_note: String(b.caption_note || ''),
    scope: String(b.scope || ''),
    test: b.test === true,
    warnings: warnings,
    // 'delivering', NOT 'pending': the preview sendMessage in Compose
    // Message has not run yet, and 'pending' is only persisted after
    // tg_ok is confirmed there. A file born 'pending' wedged the
    // draft_id behind the overwrite guard below whenever delivery
    // failed - 'pending' is non-rewritable and no Approve button ever
    // reached the operator, so the file had to be deleted by hand.
    status: 'delivering',
    created_at: new Date().toISOString()
  };
  // pending-draft guard: draft_id is caller-controlled on this PUBLIC
  // webhook, so an unguarded writeFileSync lets any caller rewrite a
  // draft the operator is still reviewing - the already-sent TG
  // message's Approve button would then publish the swapped text (the
  // queue payload snapshots d.text at Approve time). Semantic: an
  // existing DRAFTS/<id>.json may only be replaced when its moderation
  // is already decided AND a rewrite is expected:
  //   'rejected' - dead draft, the id is free for reuse;
  //   'rewrite'  - Handle TG Update set this when an Edit rewrite was
  //                dispatched to content-gen, which reuses draft_id -
  //                bounded to REWRITE_WINDOW_MS from rewrite_issued_at;
  //   'delivering' / 'deliver-failed' - the draft was saved but the
  //                preview sendMessage had not confirmed (or failed):
  //                no buttons ever reached the operator, so a retry
  //                under the same draft_id must get through. Keeping
  //                these rewritable is what prevents the wedge a
  //                born-'pending' file caused on delivery failure.
  // 'pending', 'approved' and any unknown/missing status refuse the
  // write (fail closed) - the caller must pick a fresh draft_id.
  const dpath = DRAFTS + '/' + id + '.json';
  let prev = null;
  if (fs.existsSync(dpath)) {
    // an existing-but-unreadable draft file is NOT 'absent': treating a
    // corrupt file as prev=null would let this public-webhook write
    // slip past the overwrite guard exactly when the state is damaged
    // (torn write, planted non-JSON). Fail closed - the operator
    // quarantines or removes the file, then a retry succeeds.
    try {
      prev = JSON.parse(fs.readFileSync(dpath, 'utf8'));
    } catch (e) {
      out.push({ json: { kind: 'msg', ok: false, draft_id: id,
        error: 'draft file exists but is unreadable/corrupt - refusing ' +
          'to overwrite; quarantine or remove state/drafts/' + id +
          '.json manually' } });
      continue;
    }
  }
  // 'rewrite' is a bounded window, not a standing overwrite permit:
  // the stamp is written at dispatch in Handle TG Update. Missing or
  // older than ~15min means the rewrite never arrived (dispatch
  // failure, stuck generation) - the status would otherwise keep this
  // public overwrite path open forever for anyone who knows the
  // draft_id. On expiry the draft is SEALED: prev is flipped to
  // 'rewrite-expired' and persisted, and this write is refused.
  // 'rewrite-expired' is deliberately NOT in REWRITABLE below - the
  // earlier 'treated as rejected' semantics left the door open anyway
  // ('rejected' is itself rewritable), so a decided draft_id stayed
  // publicly overwritable forever. A late-but-legit rewrite landing
  // after the seal is refused, but not silently: the moderation-draft
  // caller (content-gen) surfaces refused dispatches to the operator,
  // who can revive the draft via Reject/Edit on the preview or pick a
  // fresh draft_id.
  // $env.REWRITE_WINDOW_MS (compose passthrough) overrides the
  // window; Handle TG Update reads the same var for its approve
  // refusal - one source so the two checks cannot drift. Default
  // 15min matches the pre-env constant. Math.max(0, ...) sits BEFORE
  // the || fallback on purpose: a negative env is truthy and would
  // pass `||` untouched, making Date.now() - issued <= W false for
  // every live rewrite - a typo'd env would seal the whole Edit
  // flow instantly. Clamping <= 0 to 0 routes it through the
  // fallback exactly like NaN does.
  // SYNC-BEGIN: rewrite-window-ms
  const REWRITE_WINDOW_MS =
    Math.max(0, Number(ENV('REWRITE_WINDOW_MS'))) || 900000;
  // SYNC-END: rewrite-window-ms
  if (prev && prev.status === 'rewrite') {
    const issued = Date.parse(prev.rewrite_issued_at || '');
    if (!(Number.isFinite(issued) &&
        Date.now() - issued <= REWRITE_WINDOW_MS)) {
      // seal through a guarded re-read (the updateDraft pattern
      // Handle TG Update uses for its own rewrite-expiry close), NOT
      // by stamping the `prev` snapshot back: the rewrite itself - or
      // Compose Message flipping a parallel delivery to 'pending' -
      // can land between the readFileSync above and this write, and
      // an unguarded write-back would clobber the fresh draft file
      // with the seal. The guard demands the file still carry the
      // SAME expired 'rewrite' record, stamp included, so a re-armed
      // rewrite_issued_at vetoes too. A seal write/read failure fails
      // closed: refuse rather than overwrite a record we could not
      // settle.
      let sealed = null;
      try {
        sealed = updateDraft(id, (cur) => {
          cur.status = 'rewrite-expired';
          delete cur.rewrite_issued_at;
        }, (cur) => cur && cur.status === 'rewrite' &&
          String(cur.rewrite_issued_at || '') ===
            String(prev.rewrite_issued_at || ''));
      } catch (e) {
        out.push({ json: { kind: 'msg', ok: false, draft_id: id,
          error: 'rewrite-expired seal failed: ' +
            String(e).slice(0, 200) } });
        continue;
      }
      if (sealed) {
        out.push({ json: { kind: 'msg', ok: false, draft_id: id,
          rewrite_window_expired: true,
          error: 'rewrite window expired - draft sealed as ' +
            'rewrite-expired; use a new draft_id' } });
        continue;
      }
      // veto: the file moved on between the entry read and the seal
      // (the rewrite landed, the draft was decided, or a fresh
      // rewrite stamp appeared). Re-read and let the REWRITABLE gate
      // below judge the CURRENT record - a still-'rewrite' re-arm
      // carries a fresh stamp by construction, so honoring the
      // overwrite is correct.
      try {
        prev = JSON.parse(fs.readFileSync(dpath, 'utf8'));
      } catch (e) {
        out.push({ json: { kind: 'msg', ok: false, draft_id: id,
          error: 'draft file exists but is unreadable/corrupt - refusing ' +
            'to overwrite; quarantine or remove state/drafts/' + id +
            '.json manually' } });
        continue;
      }
    }
  }
  // 'rewrite-expired' is intentionally absent: it is the terminal seal
  // the window above lands on, not a rewritable status
  const REWRITABLE = ['rejected', 'rewrite', 'delivering',
    'deliver-failed'];
  if (prev && REWRITABLE.indexOf(prev.status) === -1) {
    out.push({ json: { kind: 'msg', ok: false, draft_id: id,
      error: 'draft exists, status "' + String(prev.status) +
        '" - refusing to overwrite a draft under moderation; ' +
        'reject it or use a new draft_id' } });
    continue;
  }
  try {
    writeJsonAtomic(dpath, draft);
  } catch (e) {
    // an unguarded throw exits the node before Respond Draft - the
    // moderation-draft caller gets a bare execution failure and later
    // items in the batch never run. Answer in-band instead (same
    // discipline as the saveDraft wraps in Handle TG Update).
    out.push({ json: { kind: 'msg', ok: false, draft_id: id,
      error: 'draft file write failed: ' + String(e).slice(0, 200) } });
    continue;
  }

  // resolvable media become binary items for the TG SendPhoto node
  // (multipart needs a real HTTP node - Buffer bodies do not survive
  // the task-runner proxy in helpers.httpRequest)
  const mediaFailed = [];
  const mediaOk = [];
  // size caps BEFORE base64-ing into item memory: every photo item
  // carries the whole file as base64 (+33%), so an unbounded read lets
  // one huge image balloon the execution payload - and Telegram's
  // sendPhoto refuses photos over ~10MB anyway. 5MB per file, 18MB
  // total leaves headroom under both limits; oversized entries land in
  // media_failed so the preview shows them as attach failures.
  const MAX_MEDIA_BYTES = 5 * 1024 * 1024;
  const MAX_MEDIA_TOTAL = 18 * 1024 * 1024;
  let mediaBytes = 0;
  for (const orig of draft.media) {
    const resolved = resolveMedia(orig);
    if (!resolved) { mediaFailed.push(orig); continue; }
    try {
      // re-canonicalize at use time: resolveMedia's underRoot verdict
      // ran on the candidate path a moment ago, and a symlink inside
      // materials/ re-pointed in between would make statSync/
      // readFileSync follow the NEW target - a check-then-use escape
      // out of the read-only mount. Verify the freshly resolved
      // canonical path against the root and read THAT path, so a
      // swapped link fails closed instead of smuggling an outside
      // file into the preview.
      const real = fs.realpathSync(resolved);
      if (!(real === MEDIA_ROOT_REAL ||
          real.startsWith(MEDIA_ROOT_REAL + '/'))) {
        mediaFailed.push(orig);
        continue;
      }
      const sz = fs.statSync(real).size;
      if (sz > MAX_MEDIA_BYTES) {
        mediaFailed.push(orig + ' (>5MB per-file cap)');
        continue;
      }
      if (mediaBytes + sz > MAX_MEDIA_TOTAL) {
        mediaFailed.push(orig + ' (over the 18MB total media cap)');
        continue;
      }
      mediaOk.push({
        path: real,
        base64: fs.readFileSync(real).toString('base64'),
        mime: mimeOf(real),
        fname: real.split('/').pop()
      });
      mediaBytes += sz;
    } catch (e) { mediaFailed.push(orig); }
  }

  for (let i = 0; i < mediaOk.length; i++) {
    const m = mediaOk[i];
    out.push({
      json: {
        kind: 'photo', draft_id: id, chat_id: chatId,
        caption: '[DRAFT ' + id + ' | ' + draft.platform + '] media ' +
          (i + 1) + '/' + mediaOk.length + ' - ' + m.fname
      },
      binary: {
        file: { data: m.base64, mimeType: m.mime, fileName: m.fname }
      }
    });
  }
  out.push({
    json: {
      kind: 'msg', draft_id: id, chat_id: chatId,
      media_ok: mediaOk.map((m) => m.path),
      media_failed: mediaFailed
    }
  });
}
return out;

const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const DRAFTS = STATE + '/drafts';
// same tmp+rename write discipline as the sibling Code nodes: a crash
// mid-writeFileSync leaves a torn draft JSON, and Prepare Draft's
// overwrite guard then fails closed on it - the draft stays wedged
// until manual cleanup.
// SYNC: sibling copies live in Handle TG Update and Prepare Draft
// (this workflow), Publish Tick (sp-publish, hardened 0o600 variant),
// Generate Drafts (sp-content-gen) and Resolve Chat + Webhook
// (sp-tg-setup). n8n Code nodes cannot share a prelude - replicate
// any fix to every copy by hand.
// SYNC-BEGIN: write-json-atomic
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic
const token = ENV('TELEGRAM_BOT_TOKEN');
// tg() never throws: a sendMessage transport error used to reject
// Promise.all and kill the node BEFORE Respond Draft ran - the
// moderation-draft caller saw a bare execution failure while other
// markers' previews still landed in the background, and a retry under
// a draft_id already persisted 'pending' hit Prepare Draft's
// overwrite guard. null degrades to a per-marker tg_ok:false - the
// composeOne code below already handles r === null. Same contract as
// the sibling tg() in Handle TG Update.
const tg = async (method, body) => {
  try {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + token + '/' + method,
      body: body,
      json: true,
      // explicit 30s timeout, same as the tg() helpers in Handle TG
      // Update and Publish Tick: helpers.httpRequest is unbounded by
      // default, so a hung api.telegram.org socket would stall this node
      // and the moderation-draft webhook response behind it
      timeout: 30000
    });
  } catch (e) { return null; }
};

const items = $input.all();
// A batch can carry several drafts: Prepare Draft emits each draft's
// photo items immediately BEFORE its 'msg' marker, and Merge Media
// preserves that order, so the photo results arriving here belong to
// the markers in sequence - marker N owns the next media_ok.length
// results. Composing only the FIRST marker (.find) would drop every
// other preview in the batch, so every marker is processed in turn.
const markers = [];
const photoResults = [];
for (const it of items) {
  const j = it.json || {};
  if (j.kind === 'msg') markers.push(j); else photoResults.push(j);
}
if (!markers.length) {
  return [{ json: { ok: false, error: 'no msg marker item in batch' } }];
}
const composeOne = async (marker, myPhotos) => {
  if (marker.ok === false) return marker;
  const chatId = marker.chat_id || '';
  const id = marker.draft_id || '';
  if (!id || !chatId) return { ok: false, error: 'no draft context' };
  let draft = null;
  try { draft = JSON.parse(fs.readFileSync(DRAFTS + '/' + id + '.json', 'utf8')); } catch (e) {}
  if (!draft) return { ok: false, error: 'draft file missing: ' + id };
  // warnings/media come from a re-read disk file, not a schema: a
  // corrupt or legacy draft (warnings saved as a string, media as an
  // object) would throw TypeError on .map/.length below, reject
  // Promise.all and kill the node BEFORE Respond Draft - the same
  // bare-execution-failure outcome every other path here answers
  // in-band to avoid. Coerce to arrays so a malformed draft degrades
  // to empty sections instead.
  const warnings = Array.isArray(draft.warnings) ? draft.warnings : [];
  const media = Array.isArray(draft.media) ? draft.media : [];

  // photo results = this marker's slice of the merged batch (the driver
  // below hands each marker the next media_ok.length items). Successful
  // sendPhoto responses carry ok:true; failures arrive as error objects
  // (the HTTP node runs with onError=continue). Map results back to
  // paths through the resolvable list - item order matches media_ok
  // order.
  const resolvable = Array.isArray(marker.media_ok) ? marker.media_ok : [];
  const failed = Array.isArray(marker.media_failed) ? marker.media_failed.slice() : [];
  let mediaSent = 0;
  let seq = 0;
  for (const resp of myPhotos) {
    const idx = seq;
    seq++;
    if (resp.ok === true) { mediaSent++; continue; }
    failed.push(resolvable[idx] || 'photo upload failed');
  }
  draft.media_sent = mediaSent;

  // surrogate-safe truncation for every string that lands in msg: a
