      const dirFiles = (s) => {
        try { return fs.readdirSync(PUBLISH + s); } catch (e) { return []; }
      };
      const hasCopy = (s) => dirFiles(s).some(
        (f) => f === id + '.json' || f.startsWith(id + '.json.mv-'));
      // a .mv- copy can only come from mv()'s collision park on a
      // TERMINAL move - presence alone means the tick already decided
      // this draft, whatever payload the parked file carries
      const hasMvCopy = (s) => dirFiles(s).some(
        (f) => f.startsWith(id + '.json.mv-'));
      const probe = () => ['', '/processing', '/done', '/failed', '/skipped']
        .find((s) => hasCopy(s));
      // Queue-payload introspection shared by the queued-sync path
      // (loc === '' / '/processing') and the EEXIST branch of the
      // exclusive enqueue below. readPayload returns undefined for a
      // missing/unparseable file - 'absent or unreadable right now',
      // never proof of a competing copy. existsSync alone would leave
      // a TOCTOU gap, and a bad-JSON file is the tick's problem.
      const readPayload = (s) => {
        try {
          return JSON.parse(
            fs.readFileSync(PUBLISH + s + '/' + id + '.json', 'utf8'));
        } catch (e) { return undefined; }
      };
      // payload-field identity against the CURRENT draft (approved_at
      // is bookkeeping, not payload, and is deliberately not
      // compared): a queue file failing this carries pre-edit text -
      // answering 'already queued' would send the stale text to the
      // wall, so the caller must sync the file instead.
      const samePayload = (p) => !!p &&
        p.platform === d.platform && p.text === d.text &&
        p.image === d.image && p.test === (d.test === true) &&
        JSON.stringify(p.media || []) === JSON.stringify(d.media || []);
      // FILE identity is inode-based, not payload-based. Every writer
      // for one draft produces a byte-identical payload (fresh/enq are
      // built from the same d and approved_at is inherited), so a
      // same-payload <id>.json in a tick-owned dir is NOT proof the
      // tick claimed OUR write - a concurrent Approve's own entry
      // looks exactly the same. Treating it as ours either leaves a
      // second queue file that re-publishes next tick, or lets a veto
      // unlink delete the other callback's legitimate entry. rename()
      // preserves dev+ino, so a copy elsewhere is provably the file
      // THIS callback wrote - claimed by the tick, the intended
      // single publish - only when dev+ino match the stat captured
      // at our write. statOf nulls on failure; sameInode returns
      // undefined when either side cannot be stat'd, and callers
      // fall back to the payload compare in that case.
      const statOf = (p) => {
        try { return fs.statSync(p); } catch (e) { return null; }
      };
      const sameInode = (a, b) => ((a && b)
        ? a.dev === b.dev && a.ino === b.ino
        : undefined);
      const copyStat = (s) => statOf(PUBLISH + s + '/' + id + '.json');
      // a copy in the given dirs is FOREIGN - this draft's publish
      // already decided by the tick or a competing enqueue - unless
      // it is provably our own write (ours = the stat captured right
      // at our writeFileSync; link() shares the inode, rename()
      // carries it, so the claimed copy keeps it). Pass ours = null
      // on the pre-write checks: nothing of ours is on disk yet, so
      // every readable copy is someone else's. A .mv- copy counts as
      // foreign unconditionally - mv() only parks on the second
      // terminal move of this id, a completed record whatever its
      // inode or payload.
      const foreignDir = (dirs, ours) => dirs.find((s) => {
        if (hasMvCopy(s)) return true;
        const p2 = readPayload(s);
        if (p2 === undefined) return false;
        if (!ours) return true;
        const same = sameInode(ours, copyStat(s));
        if (same !== undefined) return !same;
        return !samePayload(p2);
      });
      // human-readable where the foreign copy sits; '' is the queue
      // ROOT - on the loc === '/processing' branch and the EEXIST
      // path a foreign copy can sit there, where the bare slice(1)
      // form would render the bogus 'already finished in /'. Give
      // the root its own wording.
      const takenNote = (s) => s === '/processing'
        ? 'in flight - the publish tick claimed it'
        : s === ''
          ? 'a competing queue entry re-appeared at the queue root'
          : 'already finished in ' + s.slice(1) + '/';
      // The locate scan is advisory only. The real guarantee is the
      // exclusive create below: link() never clobbers, so exactly one
      // enqueue attempt wins per draft even when the scan races the
      // tick's claim or a duplicate Approve callback. The tick moves
      // the queue file monotonically root -> processing/ -> terminal
      // and snapshots the root with one readdir per run, so a file
      // created now cannot be claimed before the next tick.
      let loc = probe();
      if (loc === undefined && d.status === 'approved') {
        // this draft was enqueued once - its file must exist
        // somewhere. An empty scan can only mean a rename (tick
        // claim, completion move, concurrent requeue) landed between
        // probes; rescan a few times rather than trust a phantom
        // "absent" and enqueue on top of an in-flight publish. The
        // rescans are SPACED ~150ms apart: back-to-back existsSync
        // scans finish in microseconds, so a racing rename is almost
        // never observed - the window the loop actually covers is the
        // delay, not the iteration count (still bounded at 4). If the
        // task-runner sandbox ever drops setTimeout the nap resolves
        // immediately and the loop degrades to a plain rescan.
        const nap = (ms) => (typeof setTimeout === 'function'
          ? new Promise((r) => setTimeout(r, ms))
          : Promise.resolve());
        for (let i = 0; i < 4 && loc === undefined; i++) {
          await nap(150);
          loc = probe();
        }
      }
      // durable 'already published' evidence: see publishedIds()
      // above - the ledger is indexed once per execution and only
      // NON-test records with an external_id count as publish proof
      const publishedBefore = publishedIds().has(id);
      if (loc === '/done' || publishedBefore) {
        // publish already decided - an edit marker still armed for
        // this draft is stale, drop it with the terminal answer
        clearPendingEdit(id);
        await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'already published - not re-queuing' });
        continue;
      }
      // the ENABLED gate runs BEFORE the queued-payload sync below: a
      // re-Approve on a still-queued file of a since-disabled platform
      // must get the same refusal as every other disabled-platform
      // Approve - 'queue payload updated' would claim a publish the
      // tick can only park in skipped/
      if (!ENABLED[canonPlat(String(d.platform || '').toLowerCase())]) {
        // one refusal wording for every disabled-platform Approve:
        // parked in skipped/ or not, the publish tick cannot run it -
        // answering 'Queued for publish' here would leave the file
        // cycling queue -> skipped/ while the operator believes it is
        // on the way to the wall
        await tg('answerCallbackQuery', { callback_query_id: cb.id,
          text: 'platform "' + String(d.platform || '?') +
            '" is disabled in the publish tick - Reject to close the draft, or enable it first and approve again' });
        continue;
      }
      if (loc === '' || loc === '/processing') {
        // A queue file already exists - do NOT just refuse. An Edit +
        // rewrite after the first Approve regenerates this draft under
        // the same draft_id (Prepare Draft lets a 'rewrite' draft be
        // replaced), so the queued file can hold the PRE-edit payload
        // while the operator just approved the corrected preview.
        // Operator intent on re-Approve is 'publish what I previewed':
        // sync the queued file's payload fields from the current draft
        // instead of letting the stale text reach the wall.
        const qPath = PUBLISH + loc + '/' + id + '.json';
        let q = null;
        try { q = JSON.parse(fs.readFileSync(qPath, 'utf8')); } catch (e) {}
        // retries rides with the payload like approved_at does: this
        // sync overwrites an existing queue file, so a bounded-requeue
        // counter the tick already burned onto it must survive - only
        // a fresh enqueue (enq below) resets the bound, because an
        // explicit operator re-Approve is a new retry budget
        const fresh = {
          id: id, platform: d.platform, text: d.text, image: d.image,
          media: d.media || [], test: d.test === true,
          approved_at: (q && q.approved_at) || new Date().toISOString(),
          retries: (q && q.retries) || 0
        };
        // dirs the TICK can own a copy in - for loc '' that is
        // processing/ (claimed) plus the terminal dirs; for
        // '/processing' our own write lives there, so a foreign copy
        // can only be a concurrent root enqueue or a terminal move
        const otherDirs = loc === ''
          ? ['/processing', '/done', '/failed', '/skipped']
          : ['', '/done', '/failed', '/skipped'];
        if (samePayload(q)) {
          // nothing changed since the first Approve. A claim older
          // than ~10min is a crashed tick: the publish tick reclaims
          // it into failed/ on its next run, and a plain
          // 'already queued' would hide that the draft is stuck until
          // then - tell the operator what to expect.
          const answerText = loc === '/processing'
            ? 'already queued (in-flight; if the tick crashed, it auto-recovers to failed/ after ~10min - approve again then)'
            : 'already queued';
          // the queued publish stands - the draft is decided
          clearPendingEdit(id);
          await tg('answerCallbackQuery', { callback_query_id: cb.id, text: answerText });
          continue;
        }
        // Payload differs - the draft was edited after queueing.
        // The probe() result is stale the moment it returns: the tick
        // can claim root -> processing/ or move processing/ -> a
        // terminal dir in the gap, and a blind renameSync(tmp2, qPath)
        // would then create a SECOND visible <id>.json - the claimed
        // stale payload publishes now and our fresh copy again on the
        // next tick, i.e. a duplicate wall.post. Same discipline as
        // the link()+retract enqueue below: check tick-owned dirs
        // right BEFORE writing (cheap, closes most of the window) and
        // AGAIN right after the rename, retracting our file if a copy
        // the tick already owns showed up in the gap. ours = null on
        // this pre-write scan: our fresh file is not on disk yet, so
        // EVERY readable copy is someone else's - including a
        // concurrent Approve's entry whose payload matches ours.
        const taken = foreignDir(otherDirs, null);
        if (taken !== undefined) {
          clearPendingEdit(id);
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'publish ' + takenNote(taken) +
              ' - not syncing; check the VK wall, then re-approve to retry' });
          continue;
        }
        // unique tmp name - same timestamp+random suffix as
        // writeJsonAtomic: two overlapping writes for one draft id
        // must not stage into the same file
        const tmp2 = PUBLISH + loc + '/.' + id + '.tmp-' +
          Date.now().toString(36) + '-' +
          Math.random().toString(36).slice(2, 6);
        // stat of OUR write, captured on the tmp before the rename -
        // rename() preserves dev+ino, so this is provably the file at
        // qPath afterwards AND the same file if the tick's claim
        // rename moves it to processing/. This is the inode the
        // post-write foreignDir scan and the retract unlinks compare
        // against: a same-payload copy with a different inode is a
        // competing entry, never ours.
        let ourStat = null;
        try {
          fs.writeFileSync(tmp2, JSON.stringify(fresh, null, 2));
          ourStat = statOf(tmp2);
          // same-fs rename replaces the queue file atomically - the
          // tick never reads a half-written payload
          fs.renameSync(tmp2, qPath);
        } catch (e) {
          try { fs.unlinkSync(tmp2); } catch (e2) {}
          log({ draft: id, action: 'approve-sync-failed', loc: loc,
            error: String(e).slice(0, 120) });
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'queued payload update failed - see moderation log' });
          continue;
        }
        // post-write rescan: a claim/terminal move can still have
        // landed in the gap between the pre-check and our rename (the
        // checks cannot be made atomic with the tick's rename). If a
        // foreign copy exists now, ours is a second queue entry in the
        // making - retract it. A copy carrying OUR inode is the tick
        // claiming our fresh file - the intended publish, not a
        // duplicate - and ourStat tells it apart from a concurrent
        // Approve's same-payload entry, which IS foreign.
        const taken2 = foreignDir(otherDirs, ourStat);
        if (taken2 !== undefined) {
          // Verify the file at qPath is still OUR write before
          // unlinking - inode match when statable, the payload
          // compare as fallback. If the tick already claimed it,
          // qPath is gone or holds someone else's file, and a blind
          // unlink would delete the live claim or a concurrent
          // callback's legitimate entry instead.
          const stillOurs = sameInode(ourStat, statOf(qPath));
          if (stillOurs === true ||
              (stillOurs === undefined && samePayload(readPayload(loc)))) {
            try {
              fs.unlinkSync(qPath);
              log({ draft: id, action: 'approve-sync-retracted',
                loc: loc, foreign: taken2 });
            } catch (e) {
              log({ draft: id, action: 'approve-sync-retract-failed',
                loc: loc, error: String(e).slice(0, 120) });
            }
          } else {
            log({ draft: id, action: 'approve-sync-retract-skip',
              loc: loc, foreign: taken2 });
          }
          clearPendingEdit(id);
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'a concurrent publish claimed it (' +
              takenNote(taken2) + ') - check the VK wall' });
          continue;
        }
        // residual window (documented, deliberately accepted): the
        // rescans cannot be made atomic with the tick's renames, so a
        // claim/move can still land AFTER the post-check. For loc=''
        // that is benign - the tick's rename claimed OUR fresh file,
        // so 'queue payload updated' stays accurate and the corrected
        // text is what publishes. For loc='/processing' a
        // processing/->terminal move landing after the rescan orphans
        // our fresh copy in processing/ unclaimed; stuck-claim
        // recovery parks it in failed/ ~10min later with a maybe_live
        // note while the terminal copy (pre-sync payload) already
        // published. A FOREIGN enqueue landing strictly after the
        // rescan can still stack a second entry - the inode check
        // closes the same-payload lookalike, not the tail of the
        // window. Rare either way - the ledger + the VK wall
        // disambiguate.
        // same stale-snapshot hazard as the expired-rewrite close:
        // while the draft sits in a rewritable status a
        // moderation-draft write can land between the entry loadDraft
        // and this save, and a whole-object write-back would clobber
        // the fresh file. On a veto the queued payload we just synced
        // carries pre-change text - retract it (only while the file
        // still holds OUR payload; a claimed/renamed file is the
        // tick's, not ours to delete) and let the operator decide on
        // the latest preview.
        let syncSaved = null;
        try {
          syncSaved = updateDraft(id,
            (cur) => { cur.status = 'approved'; },
            (cur) => sameDraftSnapshot(cur, d));
        } catch (e) {
          // the queue payload WAS updated - only the draft-state
          // persist failed; say so instead of a bare failure, and
          // still answer the callback (an exception here would exit
          // the loop, Respond Update never runs, the button spins)
          log({ draft: id, action: 'approve-sync-save-failed',
            loc: loc, error: String(e).slice(0, 120) });
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'queue payload updated, but draft state save failed - see moderation log' });
          continue;
        }
        if (!syncSaved) {
          // retract only while the file at qPath is still OUR write -
          // inode match when statable, payload as fallback. A
          // different inode is a competing callback's legitimate
          // entry; unlinking it would silently lose their publish.
          const stillOurs2 = sameInode(ourStat, statOf(qPath));
          if (stillOurs2 === true ||
              (stillOurs2 === undefined &&
                samePayload(readPayload(loc)))) {
            try { fs.unlinkSync(qPath); } catch (e) {}
          }
          log({ draft: id, action: 'approve-sync-vetoed-changed',
            loc: loc });
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'draft changed since this preview - not approving; decide on the latest version' });
          continue;
        }
        // draft decided - drop a stale edit marker for this draft
        clearPendingEdit(id);
        log({ draft: id, action: 'approve-sync', loc: loc });
        // For '/processing' the running tick already read the file
        // at claim time, so the swap only helps a crash-before-read
        // edge - the in-flight post may still carry the previous
        // text. The rename also resets ctime, so a crashed claim
        // waits another ~10min for stuck-claim recovery.
        await tg('answerCallbackQuery', { callback_query_id: cb.id,
          text: loc === '/processing'
            ? 'in-flight claim - payload updated, but the post may already have the previous text; check the VK wall'
            : 'queue payload updated to the latest draft' });
        // stamp the preview like a fresh approve, unless the message
        // is already stamped (operator re-approved the old preview)
        if (!/\[(APPROVED|RE-QUEUED)/.test(cb.message.text || '')) {
          await stampPreview('\n\n[APPROVED - queue updated to latest draft]');
        }
        continue;
      }
      let queued = false;
      let answer = 'Queued for publish';
      const requeue = !!loc;
      // the queue payload is materialized once here: the veto path
      // after the draft save compares the linked file against THIS
      // object (text + approved_at) before retracting, so a claim
      // rename in the gap cannot make us delete the tick's live file
      const enq = {
        id: id, platform: d.platform, text: d.text, image: d.image,
        media: d.media || [], test: d.test === true,
        approved_at: new Date().toISOString()
      };
      // stat of OUR queue write, captured on the tmp right after
      // writeFileSync - link() shares the inode and the tick's claim
      // rename carries it, so this identity survives at qFile and at
      // processing/<id>.json. Hoisted out of the enqueue block: the
      // claimedElsewhere scan and the post-save veto retract below
      // compare against it to tell 'the tick claimed our file' from
      // 'a competing entry exists'. null until our write lands.
      let ourIno = null;
      if (loc) {
        // failed/ or skipped/: the publish attempt is over, so a fresh
        // Approve means retry. Do NOT move the terminal file back
        // verbatim - an Edit in between rewrites DRAFTS/<id>.json under
        // the same draft_id, and the stale payload would publish the
        // pre-edit text to the live wall. Drop the stale copy and fall
        // through to the exclusive enqueue, which writes the CURRENT
        // draft fields through the same atomic tmp+link() path.
        // Drop EVERY dead-record copy of this id, not just the bare
        // <id>.json in loc: the claimedElsewhere scan below counts ANY
        // surviving <id>.json or <id>.json.mv-* (mv()'s collision
        // parks) in the terminal dirs as 'publish decided', so a
        // partial drop wedges the draft - e.g. failed/<id>.json.mv-*
        // next to skipped/<id>.json makes every Approve retract its
        // fresh queue file as 'already queued' until the 30-day prune.
        // The sweep covers both dead-record dirs; a file there can
        // never be re-claimed by the tick. done//processing/ are NOT
        // swept: loc being failed//skipped/ proves they held no copy
        // at probe time, so one appearing now is a publish that
        // genuinely claimed/finished in the gap - the scan must still
        // catch it and retract ours.
        for (const s of ['/failed', '/skipped']) {
          for (const f of dirFiles(s)) {
            if (f !== id + '.json' &&
                !f.startsWith(id + '.json.mv-')) {
              continue;
            }
            try {
              fs.unlinkSync(PUBLISH + s + '/' + f);
              log({ draft: id, action: 'requeue-drop-stale',
                from: s, file: f });
            } catch (e) {
              // could not remove the copy: in loc it stays parked and
              // is excluded from the retract scan below; in the other
              // dir it still fires claimedElsewhere - the safe outcome
              // (an unclearable copy exists, so the enqueue is
              // retracted rather than risking a second publish)
              log({ draft: id, action: 'requeue-drop-failed',
                from: s, file: f, error: String(e).slice(0, 120) });
            }
          }
        }
      }
      {
        // fresh approve, requeue after a terminal state, or a retry
        // after the operator cleaned the queue (file gone everywhere).
        // Atomic exclusive enqueue: write the payload to a dot-tmp the
        // publisher's *.json readdir cannot see, then link() it into
        // the queue root - link(2) fails EEXIST instead of clobbering,
        // so if a queue file appeared since the probes (concurrent
        // enqueue, tick claim racing a requeue) we lose cleanly instead
        // of overwriting it or stacking a second entry
        const tmp = PUBLISH + '/.' + id + '.tmp-' +
          Date.now().toString(36) + '-' +
          Math.random().toString(36).slice(2, 6);
        try {
          fs.writeFileSync(tmp, JSON.stringify(enq, null, 2));
          ourIno = statOf(tmp);
        } catch (e) {
          try { fs.unlinkSync(tmp); } catch (e2) {}
          log({ draft: id, action: 'approve-enqueue-write-failed',
            error: String(e).slice(0, 120) });
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'enqueue failed - see moderation log' });
          continue;
        }
        try {
          fs.linkSync(tmp, qFile);
          queued = true;
          answer = requeue ? 'Re-queued for publish' : 'Queued for publish';
          log({ draft: id, action: requeue ? 'requeue' : 'approve' });
        } catch (e) {
          if (e.code === 'EEXIST') {
            // lost the single-writer race - a queue file sits in the
            // root, so the draft IS queued; just not by us. But a
            // bare 'already queued' is only accurate when that file
            // still carries the CURRENT draft: a busy-requeue can
            // leave PRE-edit text in the queue root (this callback's
            // probes ran before the file appeared, or the file was
            // just put back by a racing enqueue), and it would go to
            // the wall as-is. Compare payload fields and apply the
            // same sync discipline as the loc === '' path above:
            // identical payload keeps 'already queued', a different
            // or unreadable one is atomically overwritten with the
            // current draft (tmp already holds enq - rename it
            // straight over the stale file). rootStat pins the inode
            // of the file that beat our link() - the retract below may
            // only delete THAT stale entry; a different inode means a
            // concurrent enqueue rewrote it and the file is their
            // legitimate queue slot, not ours to remove.
            const rootStat = statOf(qFile);
            const rootPayload = readPayload('');
            if (samePayload(rootPayload)) {
              queued = true;
              answer = 'already queued';
              log({ draft: id, action: 'approve-eexist' });
            } else {
              // payload differs (or the file is unreadable - then the
              // overwrite doubles as a repair). Guard the root before
              // AND after writing, same as the loc === '' sync: the
              // tick can claim the stale file root -> processing/ or
              // move a claim to a terminal dir in the gap, and a blind
              // renameSync would then leave a SECOND <id>.json that
              // publishes again on the next tick. The queue root
              // itself is excluded - the file there is the stale copy
              // we are replacing, not a foreign claim. ours = null:
              // our write never landed (link lost), so EVERY readable
              // copy in the tick dirs is someone else's - a
              // same-payload one is a concurrent Approve's claim, not
              // a file of ours.
              const taken = foreignDir(
                ['/processing', '/done', '/failed', '/skipped'], null);
              if (taken !== undefined) {
                // the tick already claimed or decided a copy of this
                // draft - the publish is in flight or finished, so
                // the stale root file is a second queue entry that
                // would post AGAIN on the next tick. Retract it
                // rather than sync: the tick-owned copy wins. Unlink
                // only while the root file is still THAT stale entry -
                // inode match when statable, the still-stale payload
                // as fallback. A different inode is a concurrent
                // callback's legitimate file: deleting it would lose
                // their publish, and the tick-owned copy already
                // covers this draft either way.
                const sameStale = sameInode(rootStat, statOf(qFile));
                const p3 = sameStale === undefined
                  ? readPayload('') : null;
                const stillStale = sameStale === true ||
                  (sameStale === undefined &&
                    p3 !== undefined && !samePayload(p3));
                if (stillStale) {
                  try {
                    fs.unlinkSync(qFile);
                    log({ draft: id, action: 'approve-eexist-retracted-stale',
                      foreign: taken });
                  } catch (e2) {
                    log({ draft: id, action: 'approve-eexist-retract-failed',
                      foreign: taken, error: String(e2).slice(0, 120) });
                  }
                } else {
                  log({ draft: id, action: 'approve-eexist-retract-skip',
                    foreign: taken });
                }
                queued = true;
                answer = 'already queued';
                log({ draft: id, action: 'approve-eexist-taken',
                  foreign: taken });
              } else {
                try {
                  // same retries preservation as `fresh` above: the
                  // rename replaces an existing root file, so a
                  // counter the tick persisted on it must survive the
                  // payload sync. enq was staged without retries -
                  // for the link() path (a brand-new queue file) that
                  // reset is intended, so merge only here, on the
                  // overwrite path
                  if (rootPayload && rootPayload.retries) {
                    enq.retries = rootPayload.retries;
                    fs.writeFileSync(tmp, JSON.stringify(enq, null, 2));
                  }
                  // same-fs rename replaces the stale queue file
                  // atomically - the tick never reads a half-written
                  // payload
                  fs.renameSync(tmp, qFile);
                  queued = true;
                  answer = 'queue payload updated';
                  log({ draft: id, action: 'approve-eexist-sync' });
                } catch (e2) {
                  // the pre-existing file stands - the draft is still
                  // queued with whatever payload it holds, not lost
                  queued = true;
                  answer = 'already queued';
                  log({ draft: id, action: 'approve-eexist-sync-failed',
                    error: String(e2).slice(0, 120) });
                }
              }
            }
          } else {
            answer = 'enqueue failed - see publish log';
            log({ draft: id, action: 'approve-enqueue-failed', error: String(e).slice(0, 120) });
          }
        }
        try { fs.unlinkSync(tmp); } catch (e) {}
        // post-link sanity: our fresh file only stays if NO OTHER copy
        // of this draft exists anywhere in the queue. The probes above
        // are advisory - a claimed file can land in done//failed/ in
        // the gap between link()/rename() and this check, which would
        // leave our root duplicate for the next tick (a second
        // wall.post of an already-published draft). Scan EVERY
        // in-flight/terminal dir, not just processing/. The root is
        // skipped on purpose: the only root copy is the one we just
        // linked - or, on the EEXIST-sync path, the fresh payload we
        // renamed over the stale file. The dir the stale copy was
        // found in (loc) is also skipped - the sweep above cleared it,
        // and a copy whose unlink failed stays parked there:
        // terminal-dir files are never re-claimed by the tick.
        // Identity is by inode: a bare <id>.json carrying OUR inode is
        // the tick claiming our fresh file in the gap - the intended
        // single publish, not a competing entry. Any other inode, an
        // .mv- park, or (when a stat fails) a payload that is not ours
        // counts as foreign.
        const claimedElsewhere = ['/processing', '/done', '/failed', '/skipped']
          .filter((s) => s !== loc)
          .some((s) => {
            if (hasMvCopy(s)) return true;
            // no <id>.json in this dir at all: 'no copy' is never
            // 'foreign' - a draft can never sit in all four dirs at
            // once, so letting a missing file fall through to the
            // compare below answered true unconditionally and every
            // fresh enqueue retracted itself. The identity compares
            // only run when a copy EXISTS (hasCopy, like probe()).
            if (!hasCopy(s)) return false;
            const same = sameInode(ourIno, copyStat(s));
            if (same !== undefined) return !same;
            // a stat failed - the payload compare is the only
            // identity left, and a copy that cannot be read at all
            // counts as foreign (cannot be proven ours, and a
            // duplicate is the worse failure than a retract)
            return !samePayload(readPayload(s));
          });
        if (queued && answer !== 'already queued' && claimedElsewhere) {
          // The tick reads the queue root once per run, so a file we
          // linked is still unclaimed and retracting it now is safe -
          // but only while qFile is still OUR write. If the tick
          // claimed it and a concurrent enqueue already relinked the
          // name, qFile is THEIR legitimate entry and a blind unlink
          // would lose their publish. Inode match when statable, the
          // just-written payload identity (text + approved_at are
          // unique to this callback) as fallback.
          const stillOurs = sameInode(ourIno, statOf(qFile));
          const lp = stillOurs === undefined ? readPayload('') : null;
          if (stillOurs === true ||
              (stillOurs === undefined && !!lp &&
                lp.text === enq.text &&
                lp.approved_at === enq.approved_at)) {
            try {
              fs.unlinkSync(qFile);
              queued = false;
              answer = 'already queued';
              log({ draft: id, action: 'approve-retracted' });
            } catch (e) {
              log({ draft: id, action: 'approve-retract-failed', error: String(e).slice(0, 120) });
            }
          } else {
            // nothing of ours sits at qFile - the foreign copy already
            // carries this draft's publish, so report it the same way
            queued = false;
            answer = 'already queued';
            log({ draft: id, action: 'approve-retract-skip-foreign' });
          }
        }
      }
      // persist 'approved' only once the queue file is confirmed to
      // exist - saving it before the link() left the draft stuck in a
      // non-rewritable status with NO queue file behind it whenever
      // the enqueue failed hard (non-EEXIST): Prepare Draft's
      // overwrite guard would then refuse every later rewrite of a
      // draft that was never actually queued
      if (queued) {
        // Re-read + guarded write (updateDraft/sameDraftSnapshot): a
        // draft in a rewritable status can be replaced by a
        // moderation-draft write between the entry loadDraft and this
        // save, and a whole-object saveDraft(d) would revert the fresh
        // file to the stale snapshot - the preview would then show
        // text the file and queue no longer hold. On a veto the queue
        // entry we just linked carries the pre-change text: retract it
        // (only while it is still OUR payload - a claimed file belongs
        // to the tick) and let the operator re-decide on the latest
        // preview.
        let apSaved = null;
        try {
          apSaved = updateDraft(id,
            (cur) => { cur.status = 'approved'; },
            (cur) => sameDraftSnapshot(cur, d));
        } catch (e) {
          // the queue file IS live - the publish will still run, so
          // keep the callback answer; only the draft-state persist
          // failed and the log carries the detail
          log({ draft: id, action: 'approve-save-failed',
            error: String(e).slice(0, 120) });
          answer = 'queued, but draft state save failed - see moderation log';
          apSaved = d; // persist failed - keep the queue entry live
        }
        if (!apSaved) {
          // retract only while the root file is still OUR write -
          // inode match when statable, the text + approved_at
          // identity as fallback (the timestamp is unique to this
          // callback's enq). A different inode means the tick claimed
          // our file and a concurrent enqueue relinked the name:
          // that file is THEIR legitimate entry, and deleting it
          // would silently lose their publish.
          const stillOurs = sameInode(ourIno, statOf(qFile));
          let linked = null;
          if (stillOurs === undefined) {
            try { linked = JSON.parse(fs.readFileSync(qFile, 'utf8')); } catch (e2) {}
          }
          if (stillOurs === true ||
              (stillOurs === undefined && linked &&
                linked.text === enq.text &&
                linked.approved_at === enq.approved_at)) {
            try { fs.unlinkSync(qFile); } catch (e2) {}
            log({ draft: id, action: 'approve-retracted-changed' });
          }
          queued = false;
          answer = 'draft changed since this preview - not approved; check the latest version';
          log({ draft: id, action: 'approve-vetoed-changed' });
        } else {
          // the draft is decided - a stale edit marker for it would
          // turn the next text message into a rewrite that retracts
          // this publish
          clearPendingEdit(id);
        }
      }
      await tg('answerCallbackQuery', {
        callback_query_id: cb.id,
        text: answer
      });
      // stamp the [APPROVED]/[RE-QUEUED] marker only on a FRESH
      // successful enqueue or a payload sync - 'already queued'
      // (EEXIST race with an identical payload, or a retracted
      // duplicate) must not change the message, or it would claim an
      // approval this callback did not create
      if (queued && answer !== 'already queued') {
        await stampPreview(answer === 'Re-queued for publish'
          ? '\n\n[RE-QUEUED - publish queue]'
          : answer === 'queue payload updated'
            ? '\n\n[APPROVED - queue updated to latest draft]'
            : '\n\n[APPROVED - publish queue]');
      }
    } else if (action === 'rj') {
      // Retract a queued publish BEFORE closing the draft - same
      // discipline as the Edit path below. An Approve > Reject inside
      // one publish tick leaves publish/<id>.json in the queue root
      // with status 'approved', and the next tick would wall.post the
      // text the operator just rejected. unlinkSync is race-safe
      // against the tick's root -> processing/ claim: either the file
      // is gone now, or the claim already won and the unlink just
      // ENOENTs. A processing/ copy is a live claim - unlinking could
      // race a post already sending, so warn the operator to check the
      // wall instead. done/ means the publish already finished and the
      // reject only closes the draft, not the wall post.
      const rjQueue = retractQueued(d.id, 'reject');
      const rjWarn = rjQueue === 'retracted'
        ? ' - the queued publish was retracted'
        : rjQueue === 'in-flight'
          ? ' - WARNING: the publish tick already claimed it, the rejected text may still post - check the VK wall'
          : rjQueue === 'retract-failed'
            ? ' - WARNING: could not retract the queued publish - check the publish queue'
            : rjQueue === 'already-published'
              ? ' - NOTE: this draft already published - delete the post manually if needed'
              : '';
      // same re-read + guard as the approve writes: the draft can sit
      // in a rewritable status while a moderation-draft write lands
      // mid-callback - a veto means the file moved on and stays
      // authoritative, the stale snapshot is not written back
      let rjSaved = null;
      try {
        rjSaved = updateDraft(id, (cur) => { cur.status = 'rejected'; },
          (cur) => sameDraftSnapshot(cur, d));
      } catch (e) {
        log({ draft: id, action: 'reject-save-failed',
          error: String(e).slice(0, 120) });
        await tg('answerCallbackQuery', { callback_query_id: cb.id,
          text: 'reject failed - could not save draft state' + rjWarn });
        continue;
      }
      if (!rjSaved) {
        log({ draft: id, action: 'reject-vetoed-changed' });
        await tg('answerCallbackQuery', { callback_query_id: cb.id,
          text: 'draft changed since this preview - decide on the latest version' });
        continue;
      }
      // draft decided - clear the edit marker so the next text
      // message cannot retract/revive it via the feedback path
      clearPendingEdit(id);
      log({ draft: id, action: 'reject' });
      await tg('answerCallbackQuery', { callback_query_id: cb.id,
        text: 'Rejected' + rjWarn });
      // strip the keyboard with the marker: preview_v is unchanged,
      // so an Approve button left armed on a [REJECTED] preview would
      // still pass the stale check and enqueue a real wall.post on
      // one accidental tap. The draft stays 'rejected'/rewritable -
      // revival goes through a rewrite's fresh preview, not a dead
      // button. (Approved previews keep theirs: a repeated Approve is
      // idempotent 'already queued' and the live Reject button is the
      // documented retract path.)
      await stampPreview('\n\n[REJECTED]', true);
    } else if (action === 'ed') {
      // an Edit rewrite is already in flight under this draft_id -
      // the same refusal 'ap' applies: re-arming pending_edit would
      // stack a second rewrite dispatch that Prepare Draft refuses
      // once the first lands ('rewrite' is single-slot), and the
      // press-time retractQueued would pull a publish the operator
      // has not seen decided. Live Edit buttons can survive the
      // dispatch-time keyboard strip (a silent editMessageReplyMarkup
      // failure), so this guard is what makes that leftover path
      // safe.
      if (d.status === 'rewrite') {
        const issued = Date.parse(d.rewrite_issued_at || '');
        // same env var the 'ap' refusal and Prepare Draft bound the
        // window by - one source, default 15min, same Math.max(0,...)
        // clamp so a negative env falls back instead of sealing
        // every rewrite instantly
        // SYNC-BEGIN: rewrite-window-ms
        const REWRITE_WINDOW_MS =
          Math.max(0, Number(ENV('REWRITE_WINDOW_MS'))) || 900000;
        // SYNC-END: rewrite-window-ms
        if (Number.isFinite(issued) &&
            Date.now() - issued <= REWRITE_WINDOW_MS) {
          log({ draft: id, action: 'edit-press-refused-rewrite' });
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'rewrite in flight - wait for the updated preview' });
          continue;
        }
        // expired window: seal the draft like the 'ap' path does,
        // then let THIS press run - 'rewrite-expired' is a decided
        // status and Edit is its documented recovery path (the
        // feedback handler re-reads the file and flips it back to
        // 'rewrite' with a fresh stamp). Guarded re-read as
        // everywhere: a veto means the file moved on and stays
        // authoritative.
        let edClosed = null;
        try {
          edClosed = updateDraft(id, (cur) => {
            cur.status = 'rewrite-expired';
            delete cur.rewrite_issued_at;
          }, (cur) => sameDraftSnapshot(cur, d));
        } catch (e) {
          log({ draft: id,
            action: 'edit-press-rewrite-expire-save-failed',
            error: String(e).slice(0, 120) });
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'state save failed - see moderation log' });
          continue;
        }
        if (!edClosed) {
          log({ draft: id,
            action: 'edit-press-rewrite-expire-vetoed' });
          await tg('answerCallbackQuery', { callback_query_id: cb.id,
            text: 'draft changed since this preview - decide on the latest version' });
          continue;
        }
        log({ draft: id, action: 'rewrite-expired-on-edit-press' });
        // keep the entry snapshot honest for the decided-publish
        // probe and the press-time retract below
        d = edClosed;
      }
      // Refuse BEFORE arming the edit marker or retracting anything
      // when the publish is already decided: the press-time
      // retractQueued below pulls the queue file out, and the
      // feedback path then refuses 'already approved - edit
      // discarded' anyway - the publish ends up dead while the draft
      // stays locked in non-rewritable 'approved', so the correction
      // can never land under this draft_id. 'approved' status or a
      // live queue copy means the operator must Reject first -
      // Reject retracts the entry and flips the draft to 'rejected',
      // which Edit then revives. done/ counts as decided (the post
      // is already live, an edit cannot change it); failed//skipped/
      // copies stay editable - they are dead records, not live
      // publishes. A missing dir answers false: a failed readdir
      // must not lock editing out, retractQueued below still covers
      // the real race.
      const edQueueCopy = (s) => {
        try {
          return fs.readdirSync(PUBLISH + s).some(
            (f) => f === id + '.json' || f.startsWith(id + '.json.mv-'));
        } catch (e) { return false; }
      };
      if (d.status === 'approved' || edQueueCopy('') ||
          edQueueCopy('/processing') || edQueueCopy('/done')) {
        log({ draft: id, action: 'edit-press-refused-queued',
          status: d.status });
        await tg('answerCallbackQuery', { callback_query_id: cb.id,
          text: 'already queued/published - Reject first to edit' });
        continue;
      }
      // pending_edit.json is intentionally SINGLE-SLOT across drafts:
      // arming Edit here silently replaces a marker armed on a
      // different draft - the first draft's feedback text, when it
      // arrives, is then routed to THIS draft (the only armed slot)
      // instead. Keying the marker per draft would complicate every
      // consumer (clearPendingEdit, the feedback matcher) for a rare
      // double-arm case, so the contract stays single-slot and the
      // operator is warned on overwrite below.
      let prevPend = null;
      try {
        prevPend = JSON.parse(
          fs.readFileSync(STATE + '/pending_edit.json', 'utf8'));
      } catch (e) {}
      try {
        writeJsonAtomic(STATE + '/pending_edit.json',
          { chat_id: chatId, draft_id: id, message_id: msgId });
      } catch (e) {
        log({ draft: id, action: 'edit-pending-save-failed',
          error: String(e).slice(0, 120) });
        await tg('answerCallbackQuery', { callback_query_id: cb.id,
          text: 'edit setup failed - could not save pending state' });
        continue;
      }
      const pendWarn = (prevPend && prevPend.draft_id &&
          prevPend.draft_id !== id)
        ? ' NOTE: this replaced an edit armed on ' + prevPend.draft_id +
          ' - that marker is gone; re-arm Edit on it if still needed.'
        : '';
      if (pendWarn) {
        log({ draft: id, action: 'edit-pending-replaced',
          replaced: prevPend.draft_id });
      }
      // Retract a queued publish NOW, at button-press time - not
      // when the feedback text arrives minutes later: an
      // already-approved draft can still sit in the queue root, and
      // the next tick would wall.post the PRE-edit text in that gap,
      // the arriving rewrite then landing as a second post or an
      // 'already published' surprise. The retract in the feedback
      // handler below stays as the safety net for edits set up before
      // this version deployed.
      const edQueue = retractQueued(d.id, 'edit-press');
      const edWarn = edQueue === 'retracted'
        ? ' Retracted the queued publish of the previous text.'
        : edQueue === 'in-flight'
          ? ' WARNING: the publish tick already claimed the queued file - the previous text may still post; check the VK wall.'
          : edQueue === 'retract-failed'
            ? ' WARNING: could not retract the queued publish - check the publish queue.'
            : edQueue === 'already-published'
              ? ' NOTE: a publish of this draft already finished - the rewrite needs a fresh draft_id to publish.'
              : '';
      await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'Send the corrected text as a reply' });
      await tg('sendMessage', {
        chat_id: chatId,
        text: 'Edit ' + id + ': reply to this chat with the corrected text. It goes back through content-gen for a rewrite.' + edWarn + pendWarn
      });
    } else {
      // a callback action we do not handle still needs an answer -
      // without answerCallbackQuery the client shows a spinner until
      // its own timeout and the bot looks hung
      log({ draft: id, action: 'callback-unknown',
        data: data.slice(0, 40) });
      await tg('answerCallbackQuery', { callback_query_id: cb.id,
        text: 'unknown action' });
    }
    continue;
  }

  if (upd.message) {
    const m = upd.message;
    const chatId = m.chat.id;
    // "post N": resolve item N from the stored digest and send a hype
    // brief to content-gen. Matched before the pending-edit state so an
    // exact command never becomes edit feedback.
    const pm = /^post\s+(\d{1,3})$/i.exec(String(m.text || '').trim());
    if (pm) {
      let digest = {};
      try { digest = JSON.parse(fs.readFileSync(STATE + '/digest.json', 'utf8')); } catch (e) {}
      const days = Object.keys(digest).sort().reverse();
      let it = null;
      for (const day of days) {
        if (digest[day] && digest[day][pm[1]]) { it = digest[day][pm[1]]; break; }
      }
      if (!it) {
        await tg('sendMessage', { chat_id: chatId, text: 'No digest item ' + pm[1] + '.' });
        continue;
      }
      const mt = it.metrics || {};
      const mline = Object.keys(mt).map((k) => k + ' ' + mt[k]).join(', ');
      const facts = [
        'Title: ' + (it.title || ''),
        'Source: ' + (it.source || ''),
        'Published: ' + (it.published || ''),
        mline ? 'Metrics: ' + mline : '',
        it.hype != null ? 'Hype score: ' + it.hype + '/100' : '',
        it.angle ? 'Angle: ' + it.angle : '',
        it.summary ? 'Summary: ' + it.summary : '',
        it.url ? 'Link: ' + it.url : ''
      ].filter(Boolean).join('\n');
      const brief = {
        source_type: 'hype', topic: it.title || '',
        facts: facts, links: it.url ? [it.url] : [],
        scope: 'commentary on a third-party post; do not claim it as own work',
        accents: it.angle ? [it.angle] : []
      };
      log({ action: 'post_n', n: pm[1], item: it.id || null });
      // enabled platforms only: 'all' makes content-gen write drafts
      // for DISABLED platforms too (its MAP.all fans out to every
      // writer) - the drafts then sit in moderation with no publish
      // path. Send the PUBLISH_PLATFORMS set as a comma-list;
      // Generate Drafts expands it token by token.
      const enabledList = Object.keys(ENABLED);
      if (!enabledList.length) {
        await tg('sendMessage', { chat_id: chatId,
          text: 'No publish platforms enabled (PUBLISH_PLATFORMS) - nothing to generate.' });
        continue;
      }
      try {
        const cg = await this.helpers.httpRequest({
          method: 'POST',
          url: 'http://127.0.0.1:5780/webhook/content-gen',
          // content-gen is gated by a shared-secret check
          // (X-Content-Gen-Secret vs CONTENT_GEN_WEBHOOK_SECRET, see
          // Generate Drafts in sp-content-gen) - the gate fails
          // closed, so an unset env here makes every dispatch bounce
          headers: ENV('CONTENT_GEN_WEBHOOK_SECRET')
            ? { 'X-Content-Gen-Secret': ENV('CONTENT_GEN_WEBHOOK_SECRET') }
            : {},
          body: {
            platform: enabledList.join(','), topic: brief.topic,
            source_type: 'hype',
            scope: brief.scope, accents: brief.accents, links: brief.links,
            context: JSON.stringify(brief, null, 2)
          },
          json: true, timeout: 300000
        });
        if (cgAccepted(cg)) {
          // partial refusals ride along so a silently missing
          // platform draft is not invisible to the operator
          const refused = cgRefusals(cg).length;
          await tg('sendMessage', {
            chat_id: chatId,
            text: 'Item ' + pm[1] + ' sent to content-gen - drafts will arrive here for moderation.' +
              (refused ? ' (' + refused + ' writer(s) refused: ' + cgWhy(cg) + ')' : '')
          });
        } else {
          // every results row came back ok:false (or the body itself
          // failed the ok gate): no draft is coming, so 'sent to
          // content-gen' would be a lie
          log({ action: 'post_n-refused', n: pm[1], reason: cgWhy(cg) });
          await tg('sendMessage', { chat_id: chatId,
            text: 'Item ' + pm[1] + ' not sent - content-gen produced no draft: ' + cgWhy(cg) });
        }
      } catch (e) {
        // scrubSecrets: the thrown httpRequest error can embed the
        // request config - including the X-Content-Gen-Secret header
        // this very dispatch set. Log it too: the in-band refusal
        // above records 'post_n-refused', and a thrown dispatch
        // failure deserves the same moderation.jsonl trail instead of
        // reaching only the chat
        log({ action: 'post_n-dispatch-failed', n: pm[1],
          error: scrubSecrets(e).slice(0, 200) });
        await tg('sendMessage', { chat_id: chatId, text: 'Generation failed: ' + scrubSecrets(e).slice(0, 200) });
      }
      continue;
    }
    let pend = null;
    try { pend = JSON.parse(fs.readFileSync(STATE + '/pending_edit.json', 'utf8')); } catch (e) {}
    if (pend && pend.chat_id === chatId && m.text && !m.text.startsWith('/')) {
      let d = null;
      try { d = loadDraft(pend.draft_id); } catch (e) {}
      // best-effort clear: an unlink exception must not kill the
      // update without a response (Respond Update never runs then and
      // Telegram retries the message)
      try { fs.unlinkSync(STATE + '/pending_edit.json'); } catch (e) {}
      if (!d) {
        await tg('sendMessage', { chat_id: chatId, text: 'Draft file missing - edit discarded.' });
        continue;
      }
      // belt under the press-time refusal in the 'ed' callback (and
      // the ap/rj marker clearing): an 'approved' draft must never
      // enter the rewrite path - the status flip plus
      // retractQueued below would pull a decided publish out of the
      // queue, and Prepare Draft refuses 'approved' overwrites anyway
      // so the generation could never land. Markers armed before the
      // press-time guard deployed can still reach here. 'rejected'
      // stays editable on purpose: Edit on a rejected draft is how
      // the operator revives it for another generation.
      if (d.status === 'approved') {
        log({ draft: d.id, action: 'edit-refused-approved' });
        await tg('sendMessage', { chat_id: chatId,
          text: 'Draft ' + d.id + ' is already approved - edit discarded.' });
        continue;
      }
      log({ draft: d.id, action: 'edit', feedback: m.text.slice(0, 500) });
      // the rewrite comes back through moderation-draft under the SAME
      // draft_id - flip the draft out of 'pending' first so the
      // pending-overwrite guard in Prepare Draft lets it through
      // ('rewrite' is one of the rewritable statuses; a 'pending'
      // draft refuses replacement). rewrite_issued_at bounds that
      // window: Prepare Draft only honors 'rewrite' for ~15min from
      // this stamp, then seals the draft to 'rewrite-expired' (a
      // non-rewritable status) - so a rewrite that never arrives
      // cannot leave the public-webhook overwrite path open forever
      // for anyone who knows the draft_id
      const prevStatus = d.status;
      // same updateDraft/sameDraftSnapshot discipline as the Approve/
      // Reject saves: the draft sits in a rewritable status while the
      // edit was armed, so a moderation-draft write can land between
      // the entry loadDraft and this save - a whole-object
      // saveDraft(d) would clobber the fresh file and the dispatch
      // below would regenerate off the stale snapshot. A veto means
      // the newer draft is authoritative: discard the edit and let
      // the operator re-arm it on the latest preview.
      let rw = null;
      try {
        rw = updateDraft(d.id, (cur) => {
          cur.status = 'rewrite';
          cur.rewrite_issued_at = new Date().toISOString();
        }, (cur) => sameDraftSnapshot(cur, d));
      } catch (e) {
        log({ draft: d.id, action: 'edit-save-failed',
          error: String(e).slice(0, 120) });
        await tg('sendMessage', { chat_id: chatId,
          text: 'Edit discarded - could not save draft state.' });
        continue;
      }
      if (!rw) {
        log({ draft: d.id, action: 'edit-save-vetoed-changed' });
        await tg('sendMessage', { chat_id: chatId,
          text: 'Draft ' + d.id + ' changed under this edit - ' +
            'discarded; decide on the latest preview.' });
        continue;
      }
      // dispatch off the re-read snapshot, not the entry copy - the
      // guard proved status/text match, so platform/topic/media
      // forwarding below also reflects the current file
      d = rw;
      // Safety-net retract of the queued publish BEFORE the rewrite
      // dispatch - the primary retract already ran at Edit-button
      // press (see the 'ed' callback above). This one still matters:
      // edits armed by an older version carry no press-time retract,
      // and a re-approve between press and feedback could have
      // re-linked the file. Same race-safety as everywhere: the tick
      // claims root files by rename into processing/, so unlink is
      // race-safe; a processing/ copy is a live claim and only
      // downgrades to a warning.
      const queueState = retractQueued(d.id, 'edit');
      const queueWarn = queueState === 'retracted'
        ? ' Retracted the queued publish of the previous text.'
        : queueState === 'in-flight'
          ? ' WARNING: the publish tick already claimed the queued file - the previous text may still post; check the VK wall.'
          : queueState === 'retract-failed'
            ? ' WARNING: could not retract the queued publish - check the publish queue.'
            : queueState === 'already-published'
              ? ' NOTE: a publish of this draft already finished - the rewrite needs a fresh draft_id to publish.'
              : '';
      // a failed dispatch - thrown HTTP error or an in-band refusal
      // ({ok:true, results:[...ok:false]}) - must revert the draft to
      // the previous status so the overwrite window closes NOW
      // instead of staying open until rewrite_issued_at expires, and
      // Approve stops refusing 'rewrite in flight' for a generation
      // that already ended. Re-read the file first: if the rewrite
      // already landed and flipped the draft back to 'pending', that
      // newer draft wins - do not clobber it.
      const revertRewrite = () => {
        try {
          // same updateDraft discipline as every other draft write in
          // this node: re-read and mutate the CURRENT object, and only
          // flip it back while the file still holds the 'rewrite' this
          // dispatch stamped - a rewrite delivery that landed between
          // the read and the write (status 'pending' again) vetoes the
          // revert instead of being clobbered back to prevStatus
          updateDraft(d.id, (cur) => {
            cur.status = prevStatus;
            delete cur.rewrite_issued_at;
          }, (cur) => !!cur && cur.status === 'rewrite');
        } catch (e2) {}
      };
      try {
        const cg = await this.helpers.httpRequest({
          method: 'POST',
          url: 'http://127.0.0.1:5780/webhook/content-gen',
          // same X-Content-Gen-Secret gate as the 'post N' dispatch
          // above - fails closed when CONTENT_GEN_WEBHOOK_SECRET is
          // unset
          headers: ENV('CONTENT_GEN_WEBHOOK_SECRET')
            ? { 'X-Content-Gen-Secret': ENV('CONTENT_GEN_WEBHOOK_SECRET') }
            : {},
          body: {
            mode: 'rewrite', draft_id: d.id, platform: d.platform, topic: d.topic,
            feedback: m.text, context: 'Previous draft:\n' + d.text,
            // draft fields that must survive the rewrite: Prepare Draft
            // rebuilds the draft file from the moderation-draft body,
            // so anything not forwarded through content-gen is silently
            // reset - a test:true draft would come back as a REAL post
            // (Approve then wall.posts it permanently, no verify+delete
            // and no TEST banner) and the Scope line would drop off the
            // preview. links/accents are not draft-schema fields, so
            // there is nothing to forward for them.
            test: d.test === true,
            scope: d.scope || '',
            image: d.image || '',
            media: Array.isArray(d.media) ? d.media : []
          },
          json: true, timeout: 300000
        });
        if (!cgAccepted(cg)) {
          log({ draft: d.id, action: 'rewrite-refused', reason: cgWhy(cg) });
          revertRewrite();
          await tg('sendMessage', { chat_id: chatId,
            text: 'Draft ' + d.id + ' rewrite refused by content-gen: ' +
              cgWhy(cg) + ' - the draft is back to its previous status.' + queueWarn });
        } else {
          await tg('sendMessage', {
            chat_id: chatId,
            text: 'Draft ' + d.id + ' sent for rewrite - the new version will arrive here for moderation.' + queueWarn
          });
          if (pend.message_id) {
            // the old preview is stale until the rewrite lands - strip
            // its keyboard so an Approve tap cannot race the incoming
            // rewrite (the Approve path also refuses 'rewrite' drafts)
            await tg('editMessageReplyMarkup', {
              chat_id: chatId, message_id: pend.message_id,
              reply_markup: { inline_keyboard: [] } });
          }
        }
      } catch (e) {
        revertRewrite();
        // same scrubSecrets as the post-N path: the error can embed
        // the X-Content-Gen-Secret request config. Log it too - the
        // in-band refusal above records 'rewrite-refused', and a
        // thrown dispatch failure deserves the same moderation.jsonl
        // trail instead of reaching only the chat
        log({ draft: d.id, action: 'rewrite-dispatch-failed',
          error: scrubSecrets(e).slice(0, 200) });
        await tg('sendMessage', { chat_id: chatId, text: 'Rewrite failed: ' + scrubSecrets(e).slice(0, 200) });
      }
    } else {
      await tg('sendMessage', { chat_id: chatId, text: 'Bot live. Drafts for moderation arrive here automatically.' });
    }
  }
}
return [{ json: { ok: true } }];
